// Register 1340 — the last consumer of the generated file's key
// literal comes onto env. App.tsx's GCal OAuth token exchange
// authenticated with publicAnonKey from utils/supabase/info.tsx
// (autogenerated). APPROACH, with the trade-off stated: the
// exchange now resolves the anon key from VITE_SUPABASE_ANON_KEY
// through the same string-typed resolver as AuthGate (a missing
// var fails the boot by name), and the generated file is left
// UNCONSUMED rather than edited — a regeneration may restore or
// rewrite it, but nothing reads its key export, and the pins
// below fail if any consumer ever does again. projectId (an
// identifier, not a key) still comes from the generated file.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const app = readFileSync(join(root, 'src/app/App.tsx'), 'utf8');
const api = readFileSync(join(root, 'src/app/components/api.ts'), 'utf8');
const gate = readFileSync(join(root, 'src/app/components/AuthGate.tsx'), 'utf8');

test('no client consumer reads the generated key export anymore', () => {
  assert.ok(!app.includes('publicAnonKey'));
  assert.ok(!api.includes('publicAnonKey'));
  assert.ok(!gate.includes('publicAnonKey'));
});

test('the exchange resolves its key from env, failing loudly when absent', () => {
  assert.ok(app.includes('import.meta.env.VITE_SUPABASE_ANON_KEY'));
  assert.ok(app.includes("throw new Error('VITE_SUPABASE_ANON_KEY is not set"));
  assert.ok(app.includes('Bearer ${SUPABASE_ANON_KEY}'));
});

test('projectId still comes from the generated file (identifier, not a key)', () => {
  assert.ok(app.includes('({ projectId })'));
});
